import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        int capacity = 0;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (!line.isEmpty()) { capacity = Integer.parseInt(line.substring(line.indexOf('=') + 1).trim()); break; }
        }
        final int cap = capacity;
        // Access-ordered LinkedHashMap: iteration goes from least to most recently used.
        LinkedHashMap<Integer, Integer> cache = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) { return size() > cap; }
        };
        StringBuilder out = new StringBuilder();
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String a = line.substring(4, line.length() - 1);
            if (line.charAt(0) == 'p') {
                int comma = a.indexOf(',');
                int key = Integer.parseInt(a.substring(0, comma).trim());
                int value = Integer.parseInt(a.substring(comma + 1).trim());
                cache.remove(key); // an update must also count as most recent use
                cache.put(key, value);
            } else {
                Integer v = cache.get(Integer.parseInt(a.trim()));
                out.append(v == null ? -1 : v).append('\n');
            }
        }
        System.out.print(out);
    }
}
